package main

import (
	"bufio"
	"fmt"
	"os"
)

func main() {
	in := bufio.NewReader(os.Stdin)
	out := bufio.NewWriter(os.Stdout)
	defer out.Flush()
	var n int
	if _, err := fmt.Fscan(in, &n); err != nil {
		return
	}
	total := 0
	for i := 0; i < n; i++ {
		var name string
		var qty, price int
		if _, err := fmt.Fscan(in, &name, &qty, &price); err != nil {
			break
		}
		total += qty * price
	}
	fmt.Fprintln(out, total)
}

