package main

import (
	"bufio"
	"fmt"
	"os"
	"strings"
)

func main() {
	sc := bufio.NewScanner(os.Stdin)
	sc.Buffer(make([]byte, 1024*1024), 1024*1024)
	count := map[string]int{}
	first := map[string]int{}
	i := 0
	for sc.Scan() {
		name := strings.TrimSpace(sc.Text())
		i++
		if name == "" {
			continue
		}
		count[name]++
		if _, ok := first[name]; !ok {
			first[name] = i
		}
	}
	best := ""
	for name, n := range count {
		if best == "" || n > count[best] || (n == count[best] && first[name] < first[best]) {
			best = name
		}
	}
	fmt.Println(best)
}

import java.io.BufferedReader;
import java.io.InputStreamReader;
import java.util.LinkedHashMap;
import java.util.Map;

public class Main {
    public static void main(String[] args) throws Exception {
        BufferedReader in = new BufferedReader(new InputStreamReader(System.in));
        Map<String, Integer> count = new LinkedHashMap<>();
        String line;
        while ((line = in.readLine()) != null) {
            String name = line.trim();
            if (name.isEmpty()) continue;
            count.merge(name, 1, Integer::sum);
        }
        String best = null;
        for (Map.Entry<String, Integer> e : count.entrySet()) {
            if (best == null || e.getValue() > count.get(best)) best = e.getKey();
        }
        System.out.println(best);
    }
}

use std::collections::HashMap;
use std::io::{self, Read};

fn main() {
    let mut text = String::new();
    io::stdin().read_to_string(&mut text).unwrap();
    let mut count: HashMap<&str, usize> = HashMap::new();
    let mut first: HashMap<&str, usize> = HashMap::new();
    for (i, raw) in text.lines().enumerate() {
        let name = raw.trim();
        if name.is_empty() {
            continue;
        }
        *count.entry(name).or_insert(0) += 1;
        first.entry(name).or_insert(i);
    }
    let mut best = "";
    for (name, n) in &count {
        if best.is_empty()
            || *n > count[best]
            || (*n == count[best] && first[name] < first[best])
        {
            best = *name;
        }
    }
    println!("{}", best);
}

