package main

import (
	"bufio"
	"fmt"
	"os"
	"unicode"
)

func main() {
	sc := bufio.NewScanner(os.Stdin)
	sc.Buffer(make([]byte, 1024*1024), 1024*1024)
	line := ""
	if sc.Scan() {
		line = sc.Text()
	}
	var kept []rune
	for _, r := range line {
		if unicode.IsLetter(r) || unicode.IsDigit(r) {
			kept = append(kept, unicode.ToLower(r))
		}
	}
	ok := true
	for lo, hi := 0, len(kept)-1; lo < hi; lo, hi = lo+1, hi-1 {
		if kept[lo] != kept[hi] {
			ok = false
			break
		}
	}
	if ok {
		fmt.Println("yes")
	} else {
		fmt.Println("no")
	}
}

import java.io.BufferedReader;
import java.io.InputStreamReader;

public class Main {
    public static void main(String[] args) throws Exception {
        BufferedReader in = new BufferedReader(new InputStreamReader(System.in));
        String line = in.readLine();
        if (line == null) line = "";
        StringBuilder kept = new StringBuilder();
        for (char c : line.toCharArray()) {
            if (Character.isLetterOrDigit(c)) kept.append(Character.toLowerCase(c));
        }
        boolean ok = true;
        for (int lo = 0, hi = kept.length() - 1; lo < hi; lo++, hi--) {
            if (kept.charAt(lo) != kept.charAt(hi)) {
                ok = false;
                break;
            }
        }
        System.out.println(ok ? "yes" : "no");
    }
}

use std::io::{self, Read};

fn main() {
    let mut text = String::new();
    io::stdin().read_to_string(&mut text).unwrap();
    let line = text.lines().next().unwrap_or("");
    let kept: Vec<char> = line
        .chars()
        .filter(|c| c.is_alphanumeric())
        .map(|c| c.to_ascii_lowercase())
        .collect();

    let mut ok = true;
    let (mut lo, mut hi) = (0usize, kept.len());
    while lo + 1 < hi {
        if kept[lo] != kept[hi - 1] {
            ok = false;
            break;
        }
        lo += 1;
        hi -= 1;
    }
    println!("{}", if ok { "yes" } else { "no" });
}
